        while q:
            r,c = q.popleft()
            for dr,dc in dirs4:
                p=(r+dr,c+dc)
                if p in zeros:
                    zeros.remove(p); comp.add(p); q.append(p)
        regions.append((comp, any(r in (0,h-1) or c in (0,w-1) for r,c in comp)))

    # Label 4-connected foreground components.
    ones = set((r,c) for r in range(h) for c in range(w) if grid[r][c] == 1)
